-- Enable Row Level Security on all public tables
-- The app uses Drizzle ORM via the `postgres` superuser role which bypasses RLS.
-- This blocks unauthorized access through Supabase's PostgREST API (anon/authenticated roles).

ALTER TABLE public.variation_group_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.variations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.seo_keywords ENABLE ROW LEVEL SECURITY;
