-- Deny-all policies for PostgREST roles (anon/authenticated).
-- The app connects via postgres superuser (bypasses RLS), so these only block the REST API.
CREATE POLICY "deny_postgrest_aac" ON public.aac AS RESTRICTIVE FOR ALL TO anon, authenticated USING (false) WITH CHECK (false);
